import {createActionGroup, emptyProps, props} from '@ngrx/store'
import {BackendErrorsInterface} from 'src/app/shared/types/backendErrors.interface'
import {CurrentUserInterface} from 'src/app/shared/types/currentUser.interface'
import {LoginRequestInterface} from '../types/loginRequest.interface'
import {RegisterRequestInterface} from '../types/registerRequest.interface'

/**
 * GIVEN — do not edit this file.
 *
 * createActionGroup replaces ~10 lines of createAction boilerplate per event.
 * `source` becomes the action type prefix: 'auth' + 'Login' => '[auth] Login'.
 *
 * The naming convention to memorise:
 *
 *   [feature] Verb            -> the user/component asks for something
 *   [feature] Verb success    -> the effect got a good answer
 *   [feature] Verb failure    -> the effect got a bad answer
 *
 * Only the first kind is ever dispatched by a component. The other two are
 * dispatched by effects, and consumed by reducers. That one-way flow is the
 * whole architecture.
 */
export const authActions = createActionGroup({
  source: 'auth',
  events: {
    // --- register -----------------------------------------------------------
    Register: props<{request: RegisterRequestInterface}>(),
    'Register success': props<{currentUser: CurrentUserInterface}>(),
    'Register failure': props<{errors: BackendErrorsInterface}>(),

    // --- login --------------------------------------------------------------
    Login: props<{request: LoginRequestInterface}>(),
    'Login success': props<{currentUser: CurrentUserInterface}>(),
    'Login failure': props<{errors: BackendErrorsInterface}>(),

    // --- "who am I?" on app start -------------------------------------------
    'Get current user': emptyProps(),
    // null = "not logged in", and that is a perfectly good answer here.
    'Get current user success': props<{
      currentUser: CurrentUserInterface | null
    }>(),
    'Get current user failure': emptyProps(),

    // --- logout -------------------------------------------------------------
    Logout: emptyProps(),
  },
})
